// quick script (node) to list high-priv roles and email owners
const fetch = require('node-fetch');
async function listHighPriv() {
  const res = await fetch(process.env.CONTROL_PLANE + '/api/v1/roles?filter=high_priv');
  const roles = await res.json();
  // NOTE: this is a sketch used in the GH Action, not prod
  return roles.map(r => `${r.name}, owner=${r.owner}, last_approved=${r.last_approved}`);
}
module.exports = { listHighPriv };
